function q($c,$sql){$r=$c->query($sql);return $r?:false;}
function saveUser($conn,$role,$profile){
 $username=trim($_POST['username']??'');$password=$_POST['password']??'';$nama=trim($_POST['nama_lengkap']??$_POST['nama']??'');if($nama==='')$nama=$username;
 if($username==='')throw new Exception('Username wajib diisi.');
 if($password!=='' && strlen($password)<5)throw new Exception('Password minimal 5 karakter.');
 $conn->begin_transaction();try{
  if(!empty($_POST['id'])){$id=(int)$_POST['id'];$sql="UPDATE users SET username=?,nama=?,role=?";$types='sss';$vals=[$username,$nama,$role];if($password!==''){$sql.=',password=?';$types.='s';$vals[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$types.='i';$vals[]=$id;$st=$conn->prepare($sql);$st->bind_param($types,...$vals);if(!$st->execute())throw new Exception('Username sudah digunakan.');$uid=$id;
  }else{if($password==='')throw new Exception('Password wajib diisi.');$hash=password_hash($password,PASSWORD_DEFAULT);$st=$conn->prepare('INSERT INTO users(username,password,nama,role) VALUES(?,?,?,?)');$st->bind_param('ssss',$username,$hash,$nama,$role);if(!$st->execute())throw new Exception('Username sudah digunakan.');$uid=$conn->insert_id;}
  if($profile==='siswa'){$nis=trim($_POST['nis']??'');$kelas=trim($_POST['kelas']??'');$jk=$_POST['jenis_kelamin']??'Laki-laki';$nama=trim($_POST['nama_lengkap']??'');$st=$conn->prepare('INSERT INTO siswa(user_id,nis,nama_lengkap,kelas,jenis_kelamin) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE nis=VALUES(nis),nama_lengkap=VALUES(nama_lengkap),kelas=VALUES(kelas),jenis_kelamin=VALUES(jenis_kelamin)');$st->bind_param('issss',$uid,$nis,$nama,$kelas,$jk);if(!$st->execute())throw new Exception('NIS sudah dipakai atau data siswa tidak valid.');$st=$conn->prepare('UPDATE users SET nama=? WHERE id=?');$st->bind_param('si',$nama,$uid);$st->execute();}
  if($profile==='guru'){$nip=trim($_POST['nip']??'');$jk=$_POST['jenis_kelamin']??'Laki-laki';$st=$conn->prepare('INSERT INTO guru(user_id,nip,nama_lengkap,jenis_kelamin) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE nip=VALUES(nip),nama_lengkap=VALUES(nama_lengkap),jenis_kelamin=VALUES(jenis_kelamin)');$st->bind_param('isss',$uid,$nip,$nama,$jk);if(!$st->execute())throw new Exception('Gagal menyimpan profil guru.');$st=$conn->prepare('UPDATE users SET nama=? WHERE id=?');$st->bind_param('si',$nama,$uid);$st->execute();}
  $conn->commit();return $uid;
 }catch(Throwable $e){$conn->rollback();throw $e;}
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$act=$_POST['action']??'';
  if($act==='delete'){$id=(int)$_POST['id'];if($id==($_SESSION['user']??0))throw new Exception('Akun yang sedang digunakan tidak dapat dihapus.');$st=$conn->prepare('DELETE FROM users WHERE id=?');$st->bind_param('i',$id);$st->execute();$msg='Data berhasil dihapus.';}
  elseif(in_array($act,['user','siswa','guru'],true)){$role=$act==='user'?(($_POST['role']??'')?:'admin'):$act;if($act==='user'&&!isset($_POST['role'])&&!empty($_POST['id'])){$rid=(int)$_POST['id'];$rs=$conn->query('SELECT role FROM users WHERE id='.$rid);$role=$rs?($rs->fetch_assoc()['role']??'admin'):'admin';}if(!in_array($role,['admin','guru','siswa'],true))throw new Exception('Role tidak valid.');saveUser($conn,$role,$act==='siswa'?'siswa':($act==='guru'?'guru':($_POST['profile_type']??null)));$msg='Data berhasil disimpan.';}
  elseif($act==='mapel'){$id=(int)($_POST['id']??0);$kode=trim($_POST['kode_mapel']??'');$nama=trim($_POST['nama_mapel']??'');$gid=(int)($_POST['guru_id']??0);if(!$gid)throw new Exception('Pilih guru yang mengajar mata pelajaran ini.');if($id){$st=$conn->prepare('UPDATE mapel SET kode_mapel=?,nama_mapel=?,guru_id=NULLIF(?,0) WHERE id=?');$st->bind_param('ssii',$kode,$nama,$gid,$id);}else{$st=$conn->prepare('INSERT INTO mapel(kode_mapel,nama_mapel,guru_id) VALUES(?,?,NULLIF(?,0))');$st->bind_param('ssi',$kode,$nama,$gid);}if(!$st->execute())throw new Exception('Kode mapel mungkin sudah digunakan.');$msg='Mata pelajaran disimpan.';}
  elseif($act==='mengajar'){$id=(int)($_POST['id']??0);$gid=(int)($_POST['guru_id']??0);$mid=(int)($_POST['mapel_id']??0);$find=$conn->prepare('SELECT guru_id FROM mapel WHERE id=?');$find->bind_param('i',$mid);$find->execute();$gid=(int)($find->get_result()->fetch_assoc()['guru_id']??0);if(!$gid)throw new Exception('Pilih mata pelajaran yang sudah memiliki guru.');$kelas=trim($_POST['kelas']??'');$st=$conn->prepare('INSERT IGNORE INTO kelas(nama_kelas) VALUES(?)');$st->bind_param('s',$kelas);$st->execute();$st=$conn->prepare('SELECT id FROM kelas WHERE nama_kelas=?');$st->bind_param('s',$kelas);$st->execute();$kid=(int)$st->get_result()->fetch_assoc()['id'];if($id){$st=$conn->prepare('UPDATE mengajar SET guru_id=?,mapel_id=?,kelas_id=? WHERE id=?');$st->bind_param('iiii',$gid,$mid,$kid,$id);}else{$st=$conn->prepare('INSERT INTO mengajar(guru_id,mapel_id,kelas_id) VALUES(?,?,?)');$st->bind_param('iii',$gid,$mid,$kid);}if(!$st->execute())throw new Exception('Data mengajar gagal disimpan atau sudah ada.');$msg='Data mengajar disimpan.';}
  elseif($act==='delete_related'){$table=$_POST['table']??'';$id=(int)$_POST['id'];$tables=['mapel'=>'mapel','mengajar'=>'mengajar'];if(!isset($tables[$table]))throw new Exception('Aksi tidak valid.');$st=$conn->prepare('DELETE FROM '.$tables[$table].' WHERE id=?');$st->bind_param('i',$id);$st->execute();$msg='Data dihapus.';}
 }catch(Throwable $e){$err=$e->getMessage();}
}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];if($module==='mapel')$edit=q($conn,"SELECT * FROM mapel WHERE id=$id")->fetch_assoc();elseif($module==='mengajar')$edit=q($conn,"SELECT m.*,k.nama_kelas FROM mengajar m JOIN kelas k ON k.id=m.kelas_id WHERE m.id=$id")->fetch_assoc();else $edit=q($conn,"SELECT u.*,s.nis,s.nama_lengkap,s.kelas,s.jenis_kelamin,g.nip,g.nama_lengkap AS nama_guru,g.jenis_kelamin AS jk_guru FROM users u LEFT JOIN siswa s ON s.user_id=u.id LEFT JOIN guru g ON g.user_id=u.id WHERE u.id=$id")->fetch_assoc();}
$per=(int)($_GET['per']??10);if(!in_array($per,[10,15,20,25,50,100],true))$per=10;$page=max(1,(int)($_GET['page']??1));$search=trim($_GET['cari']??'');$like="%".$conn->real_escape_string($search)."%";
$where='1=1';$select='';$from='';$order='';$columns=[];
switch($module){case 'users':case 'users2':$where="(u.username LIKE '$like' OR u.nama LIKE '$like' OR u.role LIKE '$like')";$select='u.*';$from='users u';$order='u.id DESC';$columns=$module==='users2'?['username','password','role','dibuat_pada']:['username','role','nama'];break;
case 'siswa':$where="u.role='siswa' AND (u.username LIKE '$like' OR s.nama_lengkap LIKE '$like' OR s.kelas LIKE '$like')";$select='u.id,u.username,u.role,s.nama_lengkap,s.kelas';$from='users u JOIN siswa s ON s.user_id=u.id';$order='s.nama_lengkap';$columns=['username','role','nama_lengkap','kelas'];break;
case 'guru':$where="u.role='guru' AND (u.username LIKE '$like' OR g.nama_lengkap LIKE '$like')";$select='u.id,u.username,u.role,g.nama_lengkap,GROUP_CONCAT(DISTINCT m.nama_mapel SEPARATOR ", ") mapel';$from='users u JOIN guru g ON g.user_id=u.id LEFT JOIN mapel m ON m.guru_id=g.id';$order='g.nama_lengkap';$columns=['username','role','nama_lengkap','mapel'];break;
case 'mapel':$where="(m.kode_mapel LIKE '$like' OR m.nama_mapel LIKE '$like' OR u.nama LIKE '$like')";$select='m.id,m.kode_mapel,m.nama_mapel,u.nama nama_guru';$from='mapel m LEFT JOIN guru g ON g.id=m.guru_id LEFT JOIN users u ON u.id=g.user_id';$order='m.nama_mapel';$columns=['kode_mapel','nama_mapel','nama_guru'];break;
case 'mengajar':$where="(u.nama LIKE '$like' OR k.nama_kelas LIKE '$like' OR mp.nama_mapel LIKE '$like' OR mp.kode_mapel LIKE '$like')";$select='mg.id,u.nama nama_guru,k.nama_kelas,mp.nama_mapel,mp.kode_mapel';$from='mengajar mg JOIN guru g ON g.id=mg.guru_id JOIN users u ON u.id=g.user_id JOIN kelas k ON k.id=mg.kelas_id JOIN mapel mp ON mp.id=mg.mapel_id';$order='k.nama_kelas,u.nama';$columns=['nama_guru','nama_kelas','nama_mapel','kode_mapel'];break;}
$count=q($conn,"SELECT ".($module==='guru'?'COUNT(DISTINCT u.id)':'COUNT(*)')." total FROM $from WHERE $where");$total=(int)$count->fetch_assoc()['total'];$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;$rows=q($conn,"SELECT $select FROM $from WHERE $where GROUP BY ".($module==='guru'?'u.id':($module==='users'||$module==='users2'?'u.id':($module==='siswa'?'u.id':($module==='mapel'?'m.id':'mg.id'))))." ORDER BY $order LIMIT $per OFFSET $offset");
$teachers=q($conn,"SELECT g.id,u.nama FROM guru g JOIN users u ON u.id=g.user_id ORDER BY u.nama");$mapels=q($conn,'SELECT m.id,m.kode_mapel,m.nama_mapel,m.guru_id,u.nama nama_guru FROM mapel m LEFT JOIN guru g ON g.id=m.guru_id LEFT JOIN users u ON u.id=g.user_id ORDER BY m.nama_mapel');
