<?php if(!$edit):?><section class="panel"><div class="panel-head"><h2><?=h($labels[$module])?></h2></div><form method="get" class="toolbar"><input type="hidden" name="m" value="<?=$module?>"><select name="per"><option <?=$per===10?'selected':''?>>10</option><option <?=$per===15?'selected':''?>>15</option><option <?=$per===20?'selected':''?>>20</option><option <?=$per===25?'selected':''?>>25</option><option <?=$per===50?'selected':''?>>50</option><option <?=$per===100?'selected':''?>>100</option></select><input name="cari" value="<?=h($search)?>" placeholder="Cari data..."><button class="btn primary">Cari</button></form><div class="table-wrap"><table><thead><tr><th>No</th><?php foreach($columns as $col):?><th><?=h($col==='dibuat_pada'?'Created at':($col==='password'?'Password':ucwords(str_replace('_',' ',$col))))?></th><?php endforeach;?><th>Aksi</th></tr></thead><tbody><?php $no=$offset+1;while($r=$rows->fetch_assoc()):?><tr><td><?=$no++?></td><?php foreach($columns as $col):?><td><?php if($col==='password'):?><span class="hash"><?=h($r[$col])?></span><?php elseif($col==='dibuat_pada'):?><small><?=h(date('d-m-Y H:i:s',strtotime($r[$col])))?></small><?php else:?><?=h($r[$col]??'-')?><?php endif;?></td><?php endforeach;?><td class="actions"><?php $rid=(int)$r['id'];?><a class="edit-link" href="?m=<?=$module?>&edit=<?=$rid?>">Edit</a><form method="post" onsubmit="return confirm('Yakin menghapus data ini?')"><input type="hidden" name="action" value="<?=$module==='mapel'||$module==='mengajar'?'delete_related':'delete'?>"><input type="hidden" name="table" value="<?=$module?>"><input type="hidden" name="id" value="<?=$rid?>"><button class="danger-link">Hapus</button></form></td></tr><?php endwhile;if($total===0):?><tr><td colspan="<?=count($columns)+2?>">Belum ada data yang sesuai.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><span>Menampilkan halaman <?=$page?> dari <?=$pages?> · <?=$total?> data</span><div><?php for($i=1;$i<=$pages;$i++):if($i===1||$i===$pages||abs($i-$page)<=1):?><a class="<?=$i===$page?'current':''?>" href="<?=urlPage($i)?>"><?=$i?></a><?php elseif(abs($i-$page)===2):?><a href="<?=urlPage($i)?>">…</a><?php endif;endfor;?></div></div></section><?php endif;?><?php endif;?></main></div><script src="../assets/js/app.js"></script></body></html>
